    "Support the mechanics you'd keep. You sign a message with your wallet — free, no transaction. One vote per wallet per mechanic; votes from $ARCIRCLE holders are counted separately.": "남기고 싶은 메커니즘을 지지해 주세요. 지갑으로 메시지에 서명하며 무료이고 트랜잭션도 없습니다. 메커니즘마다 지갑당 한 표이며, $ARCIRCLE 홀더의 표는 따로 집계됩니다.",
    "The signature was declined — nothing was sent.": "서명이 거절되었습니다 — 아무것도 전송되지 않았습니다.",
    "Couldn't record that vote — try again.": "투표를 기록하지 못했습니다 — 다시 시도하세요.",
    "We are here": "현재 위치",
    "Hear it first": "가장 먼저 듣기",
    "Be there when the rules are published.": "규칙이 공개되는 순간을 놓치지 마세요.",
    "Reward rules, the revenue split and every buyback are announced on these two channels first.": "리워드 규칙, 수익 배분, 모든 바이백은 이 두 채널에 가장 먼저 공지됩니다.",
    "Launch alerts on Telegram": "텔레그램 런치 알림",
    "Follow on X": "X 팔로우",
    "Questions about rewards.": "리워드에 대한 질문.",
    "Are rewards live?": "리워드가 시작됐나요?",
    "Not yet. The program is in design, and it only goes live once its rules are published on this page.": "아직입니다. 프로그램은 설계 중이며, 규칙이 이 페이지에 공개된 뒤에만 시작됩니다.",
    "Do I need to do anything now?": "지금 해야 할 일이 있나요?",
    "No. There is nothing to register or claim today. The wallet check above only shows the on-chain activity the programs are designed around.": "없습니다. 지금은 등록하거나 청구할 것이 없습니다. 위 지갑 조회는 프로그램이 기준으로 삼는 온체인 활동을 보여 줄 뿐입니다.",
    "Will buying just before a snapshot help?": "스냅샷 직전에 사면 도움이 되나요?",
    "The candidate design uses time-weighted balances and unannounced snapshots, so a balance held for a moment counts for very little.": "후보 설계는 시간 가중 잔액과 예고 없는 스냅샷을 쓰므로, 잠깐 보유한 잔액은 거의 반영되지 않습니다.",
    "Where does the money come from?": "재원은 어디서 오나요?",
    "From what the ecosystem earns: the five revenue sources above. No new $ARCIRCLE is ever minted to pay rewards.": "생태계가 버는 돈, 즉 위의 다섯 가지 수익원에서 옵니다. 리워드 지급을 위해 새 $ARCIRCLE이 발행되는 일은 없습니다.",
    "Does my vote in the poll decide the design?": "투표가 설계를 결정하나요?",
    "It is a signal, not a binding vote. It shows which mechanics the community cares about while the rules are being written.": "구속력 있는 투표가 아니라 신호입니다. 규칙을 만드는 동안 커뮤니티가 어떤 메커니즘을 중요하게 여기는지 보여 줍니다.",
    "Is holding $ARCIRCLE a claim on revenue?": "$ARCIRCLE 보유가 수익에 대한 권리인가요?",
    "No. $ARCIRCLE is a community memecoin — holding it is not a share, a claim on revenue or a right to any payment.": "아닙니다. $ARCIRCLE은 커뮤니티 밈코인이며, 보유한다고 해서 지분이나 수익에 대한 권리, 어떤 지급을 받을 권리가 생기지 않습니다.",
    "Whitepaper §8 →": "백서 8장 →",
