    "Next up": "다음 오픈",
    "New utility": "새 유틸리티",
    "Utility": "유틸리티",
    "Lock any Arc token until a date you pick. Nobody can move it before then — not even you. You can push the date later, never earlier, and every lock is public on-chain.": "원하는 날짜까지 Arc 토큰을 잠급니다. 그 전에는 누구도 — 본인도 — 꺼낼 수 없습니다. 날짜는 뒤로 미룰 수만 있고 앞당길 수는 없으며, 모든 잠금은 온체인에 공개됩니다.",
    "Locks created": "생성된 잠금",
