    "Look up a token": "토큰 조회",
    "See every lock ever made for a token — how much is locked, by whom, and when it unlocks.": "토큰에 걸린 모든 잠금을 확인하세요 — 얼마나, 누가, 언제 풀리는지.",
    "Token contract address (0x…)": "토큰 컨트랙트 주소 (0x…)",
    "Paste a token address, or pick one of your locks below.": "토큰 주소를 붙여넣거나, 아래 내 잠금에서 고르세요.",
    "Runs on ArcLock": "ArcLock으로 동작",
    "— no owner, no admin, no fee, no upgrades. You pay only Arc gas. Tokens that take a fee on transfer are recorded at the amount that actually arrives.": "— 오너도, 관리자도, 수수료도, 업그레이드도 없습니다. Arc 가스비만 냅니다. 전송 수수료가 있는 토큰은 실제로 들어온 수량으로 기록됩니다.",
    "Reading the token…": "토큰 정보를 읽는 중…",
    "Your balance": "내 잔액",
    "Pick a token to lock.": "잠글 토큰을 고르세요.",
