    "Risk found": "위험 발견",
    "How to read this": "결과 읽는 법",
    "The score starts at 100 and drops for every warning and risk; a serious risk caps it. Notes don't count against it.": "점수는 100에서 시작해 경고와 위험마다 깎이고, 심각한 위험이 있으면 상한이 걸립니다. 참고 항목은 감점되지 않습니다.",
    "Owner powers only matter while someone holds them — after ownership is renounced they show as notes.": "소유자 권한은 누군가 쥐고 있을 때만 의미가 있습니다 — 소유권을 포기하면 참고 항목으로 표시됩니다.",
    "In pool": "풀 안",
    "Top 10 wallets": "상위 10개 지갑",
    "Largest wallets": "큰 지갑 순위",
    "No wallets besides the pool, burned and locked tokens.": "풀·소각·잠금 외에는 보유 지갑이 없습니다.",
    "From the token's full transfer history; balances read live.": "토큰의 전체 전송 기록 기준, 잔액은 실시간.",
    "From recent transfer history; balances read live.": "최근 전송 기록 기준, 잔액은 실시간.",
    "Open on the explorer": "익스플로러에서 열기",
    "That isn't a token address — it should start with 0x and be 42 characters long.": "토큰 주소가 아닙니다 — 0x로 시작하는 42자여야 합니다.",
    "Couldn't read that address from Arc right now — try again in a moment.": "지금 Arc에서 그 주소를 읽지 못했습니다 — 잠시 후 다시 시도하세요.",
    "No contract at this address": "이 주소에는 컨트랙트가 없습니다",
    "Nothing is deployed here on Arc — it isn't a token.": "Arc에 배포된 것이 없습니다 — 토큰이 아닙니다.",
    "Not a standard token": "표준 토큰이 아님",
    "It doesn't answer the basic ERC-20 calls (name, symbol, decimals, supply).": "기본 ERC-20 호출(이름, 심볼, 소수점, 공급량)에 응답하지 않습니다.",
    "Standard ERC-20 token": "표준 ERC-20 토큰",
    "Upgradeable proxy": "업그레이드 가능한 프록시",
    "Its code lives behind a beacon and can be switched to new code.": "코드가 비콘 뒤에 있어 새 코드로 바꿀 수 있습니다.",
    "Fixed code": "고정된 코드",
    "Not a proxy — the code you see can't be swapped out.": "프록시가 아닙니다 — 지금 코드를 바꿀 수 없습니다.",
    "ARCIRCLE PAD core coin": "ARCIRCLE PAD 코어 코인",
    "$ARCIRCLE, launched on Argus — one pool, supply in a single locked position.": "Argus에서 런치한 $ARCIRCLE — 풀 하나, 공급량은 하나의 잠긴 포지션에.",
    "Launched on ArcPad": "ArcPad에서 런치됨",
    "The standard ArcPad token, launched through the ArcPad factory with its pool created in the same transaction.": "ArcPad 팩토리로 런치된 표준 ArcPad 토큰으로, 같은 트랜잭션에서 풀이 만들어졌습니다.",
    "Not an ArcPad launch": "ArcPad 런치 아님",
    "Launched somewhere else, so every check below is the generic one.": "다른 곳에서 런치되어 아래는 모두 일반 점검입니다.",
    "No owner": "소유자 없음",
    "The contract has no owner function — there's no admin wallet to call anything.": "소유자 함수가 없습니다 — 무언가를 호출할 관리자 지갑이 없습니다.",
    "Ownership renounced": "소유권 포기됨",
    "The owner is the zero/dead address, so owner-only functions can't be called.": "소유자가 0/dead 주소라 소유자 전용 함수를 호출할 수 없습니다.",
    "Owned by a contract": "컨트랙트가 소유",
    "Owned by a wallet": "지갑이 소유",
    "Owner:": "소유자:",
    "Often a multisig or timelock — check who controls it.": "대개 멀티시그나 타임락입니다 — 누가 관리하는지 확인하세요.",
    "One wallet can still call owner-only functions.": "지갑 하나가 아직 소유자 전용 함수를 호출할 수 있습니다.",
    "Role-based permissions": "역할 기반 권한",
    "Access is managed with roles (AccessControl) — admins may hold mint or pause rights.": "역할(AccessControl)로 권한을 관리합니다 — 관리자가 발행이나 정지 권한을 가질 수 있습니다.",
    "No dangerous switches found": "위험한 스위치 없음",
    "No mint, pause, blacklist, fee or trading switches in its code.": "코드에 발행·정지·블랙리스트·수수료·거래 스위치가 없습니다.",
    "Can mint new tokens": "새 토큰 발행 가능",
    "More supply can be created at any time, diluting every holder.": "언제든 공급량을 늘려 모든 보유자를 희석시킬 수 있습니다.",
    "Can pause transfers": "전송 정지 가능",
    "Trading and transfers can be frozen.": "거래와 전송을 멈출 수 있습니다.",
    "Can block wallets": "지갑 차단 가능",
    "Specific wallets can be stopped from selling or moving tokens.": "특정 지갑의 매도나 전송을 막을 수 있습니다.",
    "Code can be upgraded": "코드 업그레이드 가능",
    "The contract's logic can be replaced with different code.": "컨트랙트 로직을 다른 코드로 바꿀 수 있습니다.",
    "Can change buy/sell fees": "매수·매도 수수료 변경 가능",
    "The tax on trades can be raised after you buy.": "매수 후에 거래 세금을 올릴 수 있습니다.",
    "Can cap trade or wallet size": "거래·지갑 한도 설정 가능",
    "Limits can be set so that larger sells don't go through.": "한도를 걸어 큰 매도가 체결되지 않게 할 수 있습니다.",
    "Trading can be switched off": "거래를 끌 수 있음",
    "The owner controls whether the token can be traded.": "소유자가 거래 가능 여부를 정합니다.",
    "Can pull tokens out of the contract": "컨트랙트 안의 토큰 인출 가능",
    "Tokens or USDC held by the contract itself can be withdrawn by the owner.": "컨트랙트가 보유한 토큰이나 USDC를 소유자가 인출할 수 있습니다.",
