    "Hook:": "훅:",
    "Is it a standard token? Can its code be swapped out? Was it launched on ArcPad or Argus?": "표준 토큰인가요? 코드를 바꿀 수 있나요? ArcPad나 Argus에서 런치했나요?",
    "A dry-run buy, sell and transfer — does it go through, and how much tax is taken?": "매수·매도·전송을 모의 실행 — 실제로 되는지, 세금이 얼마나 떼이는지.",
    "Where it trades, how deep the pool is, how old it is, and whether people actually sell.": "어디서 거래되는지, 풀이 얼마나 깊은지, 얼마나 오래됐는지, 실제로 파는 사람이 있는지.",
    "How spread out the supply is, who deployed it and what they still hold.": "공급량이 얼마나 분산됐는지, 누가 배포했고 아직 얼마나 가졌는지.",
    "Mints after launch, ownership changes, pauses and big moves — from the token's own log.": "런치 후 발행, 소유권 변경, 정지, 대량 이동 — 토큰 자체 기록에서.",
    "Holder growth over time": "시간에 따른 보유자 증가",
    "Watch alerts on Telegram": "텔레그램 감시 알림",
    "A public scan API for other Arc apps": "다른 Arc 앱을 위한 공개 스캔 API",
    "Reads Arc directly — the buy and sell checks are dry runs, nothing is signed or spent — plus Dexscreener for market data. An automated check, not advice: a clean scan can't rule out every risk, and a warning doesn't always mean a scam.": "Arc를 직접 읽습니다 — 매수·매도 점검은 모의 실행이라 서명도, 지출도 없습니다 — 시장 데이터는 Dexscreener를 씁니다. 자동 점검일 뿐 투자 조언이 아닙니다: 깨끗한 결과가 모든 위험을 배제하지 않고, 경고가 곧 사기를 뜻하지도 않습니다.",
    "Launched on Argus": "Argus에서 런치됨",
    "Launched through an Argus portal: a Uniswap v4 pool with the supply in one locked position.": "Argus 포털로 런치됨: 공급량이 하나의 잠긴 포지션에 들어간 Uniswap v4 풀.",
    "Not a launchpad token": "런치패드 토큰 아님",
    "Not launched through ArcPad or Argus, so every check below is the generic one.": "ArcPad나 Argus로 런치되지 않아 아래는 모두 일반 점검입니다.",
    "No trade simulation": "거래 모의 실행 없음",
    "There was no holder the dry run could act as.": "모의 실행에 쓸 보유자가 없었습니다.",
    "Trade simulation unavailable": "거래 모의 실행 불가",
    "The Arc RPC didn't accept the dry run, so buying and selling weren't simulated.": "Arc RPC가 모의 실행을 받지 않아 매수·매도를 시뮬레이션하지 못했습니다.",
    "Trades in its ArcPad pool": "ArcPad 풀에서 거래됨",
    "Trades in its Argus pool": "Argus 풀에서 거래됨",
    "A Uniswap v4 pool created at launch, its liquidity locked for good — read from the chain because Dexscreener hasn't listed it yet.": "런치 때 만들어진 Uniswap v4 풀로 유동성이 영구 잠겨 있습니다 — Dexscreener에 아직 없어 체인에서 직접 읽었습니다.",
    "A Uniswap v4 pool created at launch — read from the chain because Dexscreener hasn't listed it yet.": "런치 때 만들어진 Uniswap v4 풀 — Dexscreener에 아직 없어 체인에서 직접 읽었습니다.",
    "Deployer still holds tokens": "배포자가 아직 보유 중",
    "Deployer holds none": "배포자 보유 없음",
    "The wallet that created the token has passed on everything it minted.": "토큰을 만든 지갑이 발행한 물량을 모두 넘겼습니다.",
    "Minted after launch": "런치 후 추가 발행",
    "No mints after launch": "런치 후 추가 발행 없음",
    "Every token that exists was minted when it was created.": "지금 있는 토큰은 모두 생성 시점에 발행됐습니다.",
    "Renounced on-chain": "체인에서 소유권 포기 확인",
