    "Has been paused before": "정지된 적 있음",
    "Code was upgraded": "코드가 업그레이드됨",
    "Ownership went to the zero address.": "소유권이 0 주소로 넘어갔습니다.",
    "Set by Argus at launch and fixed in its pool hook; 90% of it goes to the creator.": "Argus가 런치 때 정해 풀 훅에 고정했습니다. 그중 90%는 생성자 몫입니다.",
    "Set by Argus at launch and fixed in its pool hook.": "Argus가 런치 때 정해 풀 훅에 고정했습니다.",
    "Selling fails": "매도 실패",
    "Buying fails": "매수 실패",
