    "How far one sell of a fixed size would push the price down. Big moves mean you'd get noticeably less than the price you see.": "정해진 금액을 한 번 팔 때 가격이 얼마나 밀리는지입니다. 크게 밀리면 보이는 가격보다 확실히 적게 받습니다.",
