    "wallets in": "참여 지갑",
    "Can I get my USDC back?": "USDC를 돌려받을 수 있나요?",
    "Yes — any amount, any time until the 72 hours are up. \"Withdraw my contribution\" sends it straight back from the escrow; nobody else can move your USDC while the raise is open.": "네 — 72시간이 끝나기 전까지는 원하는 금액을 언제든 인출할 수 있어요. \"내 참여금 인출\"을 누르면 에스크로에서 바로 돌려받고, 모금이 열려 있는 동안에는 다른 누구도 내 USDC를 옮길 수 없어요.",
    "What happens when the 72 hours end?": "72시간이 끝나면 어떻게 되나요?",
    "Contributions and withdrawals stop. Everything the escrow holds is then split in one transaction: 80% to the recipient wallet, 15% to the treasury wallet and 5% to the platform wallet — the addresses above, fixed in the contract.": "참여와 인출이 멈춰요. 그 뒤 에스크로에 있는 전액이 한 번의 트랜잭션으로 나뉘어요: 수령 지갑 80%, 트레저리 지갑 15%, 플랫폼 지갑 5% — 위에 표시된, 컨트랙트에 고정된 주소들이에요.",
    "Who can split it, and can it happen early?": "누가 분배할 수 있고, 일찍 할 수도 있나요?",
    "Only the recipient wallet can call the split, and the contract refuses it until the raise has closed.": "수령 지갑만 분배를 실행할 수 있고, 모금이 마감되기 전에는 컨트랙트가 거부해요.",
    "How is the new coin shared with contributors?": "새 코인은 참여자에게 어떻게 배분되나요?",
    "Not decided yet — it will be announced here before the raise opens. The list of contributors at the close is public on-chain, so anyone can check who was in and how much.": "아직 정해지지 않았어요 — 모금이 시작되기 전에 여기에 공지할게요. 마감 시점의 참여자 명단은 온체인에 공개되어 있어서 누가 얼마나 참여했는지 누구나 확인할 수 있어요.",
    "Is the contract's code public?": "컨트랙트 코드는 공개되어 있나요?",
    "Yes — the escrow's source is verified on the explorer, so what it does can be read line by line.": "네 — 에스크로 소스가 탐색기에서 검증되어 있어서 동작을 한 줄씩 읽어볼 수 있어요.",
    "The source hasn't been verified on the explorer yet. The code is in the project's repository (contracts/BigPadEscrow.sol); this note changes once it is verified.": "아직 탐색기에서 소스가 검증되지 않았어요. 코드는 프로젝트 저장소(contracts/BigPadEscrow.sol)에 있고, 검증되면 이 안내가 바뀌어요.",
    "Opens in": "시작까지",
    "Opening any moment": "곧 시작해요",
    "No contributors yet — be the first dot.": "아직 참여자가 없어요 — 첫 번째 점이 되어보세요.",
    "Every contributor becomes a dot here once the raise opens.": "모금이 시작되면 참여자 한 명 한 명이 여기에 점으로 나타나요.",
    "Source verified": "소스 검증됨",
