    "Every Uniswap v4 pool an Arc token trades in — price, depth, every LP position and how much of it is locked. Add or remove liquidity and lock your LP without leaving ARCIRCLE PAD.": "Arc 토큰이 거래되는 모든 Uniswap v4 풀 — 가격, 깊이, 모든 LP 포지션과 잠긴 비중까지. 유동성 추가·제거와 LP 잠금을 ARCIRCLE PAD 안에서 바로 할 수 있어요.",
