    "Pool created — your position is below.": "풀을 만들었습니다 — 포지션은 아래에 있습니다.",
    "A new Uniswap v4 pool on Arc, with no hook. You set its first price and make the first deposit.": "훅 없는 새 Uniswap v4 풀을 Arc에 만듭니다. 첫 가격과 첫 예치를 직접 정합니다.",
