    "Market price now": "현재 시장 가격",
    "There's no market price for this token yet — you're setting it. Get it wrong and arbitrage bots take the difference from your deposit.": "이 토큰은 아직 시장 가격이 없어 직접 정하게 됩니다. 잘못 정하면 차익거래 봇이 그 차이를 예치금에서 가져갑니다.",
