    "First, a one-time approval lets the vote contract burn $ARCIRCLE from your wallet — only when you vote.": "먼저 한 번만 승인하면, 투표할 때에만 투표 컨트랙트가 지갑의 $ARCIRCLE을 소각할 수 있어요.",
    "Approve in wallet…": "지갑에서 승인…",
