    "Contributions and withdrawals stop. The escrow splits everything: 80% recipient, 15% treasury, 5% platform.": "참여와 출금이 멈춥니다. 에스크로가 전액을 나눠 보냅니다: 수령자 80%, 트레저리 15%, 플랫폼 5%.",
    "Contributor airdrop": "참여자 에어드롭",
