    "Approve and send. The Arc adapter locks your $ARCIRCLE and LayerZero delivers a message; the other chain mints the same amount to your address.": "승인하고 보내면 Arc 어댑터가 $ARCIRCLE을 잠그고 LayerZero가 메시지를 전달해요. 상대 체인이 같은 양을 당신 주소로 발행해요.",
    "Back to Arc": "다시 Arc로",
    "Send from Solana or Robinhood Chain. The tokens are burned there and the adapter unlocks the same amount to you on Arc.": "솔라나나 로빈후드 체인에서 보내면 그쪽 토큰이 소각되고, 어댑터가 Arc에서 같은 양을 풀어줘요.",
    "Between Solana and Robinhood": "솔라나 ↔ 로빈후드",
    "Burned on one, minted on the other. Arc's locked amount doesn't change, so the total still adds up.": "한쪽에서 소각되고 다른 쪽에서 발행돼요. Arc에 잠긴 양은 그대로라 합계가 항상 맞아요.",
    "Each chain has its own market. When prices drift apart, buying where it's cheaper and selling where it's higher pulls them together.": "체인마다 시장이 따로 있어요. 가격이 벌어지면 싼 곳에서 사서 비싼 곳에서 파는 거래가 가격을 다시 맞춰요.",
    "Built on LayerZero V2 OFT: an adapter on Arc for the existing token, mint/burn OFTs on the other chains. Not decided yet: the second verifier, daily limits, pool venues on Solana and Robinhood Chain, and the launch date.": "LayerZero V2 OFT 기반: 기존 토큰을 위한 Arc 어댑터와 다른 체인의 발행/소각 OFT. 아직 미정: 두 번째 검증자, 일일 한도, 솔라나·로빈후드 체인의 풀 위치, 출시일.",
