    "Compared with simply holding the same tokens, for this position's own price range — a narrow range loses more once the price leaves it. Fees earned are not included.": "이 포지션의 가격 범위 기준으로, 같은 토큰을 그냥 보유했을 때와 비교한 값이에요 — 범위가 좁을수록 가격이 범위를 벗어나면 손실이 커져요. 받은 수수료는 포함하지 않아요.",
